<section class="content-area" aria-labelledby="page-title"><div class="container-fluid"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 id="page-title" class="h3">Assistant Logs</h1><p class="text-muted mb-0">Review sample conversations and triage outcomes.</p></div></div>
<div class="card"><div class="card-body"><div class="row g-3 mb-3"><div class="col-md-7"><label class="form-label" for="logSearch">Search logs</label><input class="form-control" id="logSearch" type="search" placeholder="Search user or message"></div><div class="col-md-5"><label class="form-label" for="tierFilter">Triage tier</label><select class="form-select" id="tierFilter"><option value="">All tiers</option><option value="informational">Informational</option><option value="consult">Consult a professional</option><option value="urgent">Urgent</option></select></div></div>
<div class="table-responsive"><table class="table align-middle"><thead><tr><th>Date</th><th>User</th><th>First message</th><th>Triage</th><th>Status</th><th><span class="visually-hidden">Actions</span></th></tr></thead><tbody id="logsTableBody"><?php foreach ($conversations as $conversation): $firstMessage = $conversation->messages[0]->text ?? ''; ?><tr data-tier="<?= htmlspecialchars($conversation->tier, ENT_QUOTES, 'UTF-8') ?>"><td><?= htmlspecialchars($conversation->date, ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($conversation->user, ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($firstMessage, ENT_QUOTES, 'UTF-8') ?></td><td><span class="triage-badge triage-badge--<?= htmlspecialchars($conversation->tier, ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars($conversation->tier === 'consult' ? 'Consult a professional' : ucfirst($conversation->tier), ENT_QUOTES, 'UTF-8') ?></span></td><td><?= htmlspecialchars($conversation->status, ENT_QUOTES, 'UTF-8') ?></td><td><button class="btn btn-sm btn-outline-primary" type="button" data-bs-toggle="modal" data-bs-target="#conversation<?= (int)$conversation->id ?>">View</button></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php foreach ($conversations as $conversation): ?><div class="modal fade" id="conversation<?= (int)$conversation->id ?>" tabindex="-1" aria-labelledby="conversationTitle<?= (int)$conversation->id ?>" aria-hidden="true"><div class="modal-dialog modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5" id="conversationTitle<?= (int)$conversation->id ?>">Conversation · <?= htmlspecialchars($conversation->user, ENT_QUOTES, 'UTF-8') ?></h2><button class="btn-close" type="button" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><?php foreach ($conversation->messages as $message): ?><div class="border rounded p-3 mb-2"><strong><?= htmlspecialchars(ucfirst($message->role), ENT_QUOTES, 'UTF-8') ?></strong><time class="text-muted small ms-2"><?= htmlspecialchars($message->time, ENT_QUOTES, 'UTF-8') ?></time><p class="mb-0 mt-2"><?= htmlspecialchars($message->text, ENT_QUOTES, 'UTF-8') ?></p></div><?php endforeach; ?></div></div></div></div><?php endforeach; ?></div></section>
